import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.transactions().listTransactions(Map.of("limit", 50, "offset", 0));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("transactions")) {
    Map<?, ?> transaction = (Map<?, ?>) row;
    System.out.println(transaction.get("transaction_no") + " " + transaction.get("total_records"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

get_transaction.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.transactions().getTransaction("IMPORT-2026-0001");
Map<?, ?> transaction = (Map<?, ?>) response.getMap();
System.out.println(transaction.get("transaction_no") + " " + transaction.get("total_records"));
for (Object row : (List<?>) transaction.get("by_type")) {
    Map<?, ?> type = (Map<?, ?>) row;
    System.out.println(type.get("type") + " " + type.get("count"));
}

