import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.transactions().listTransactionItems("IMPORT-2026-0001",
        Map.of("type", "product", "limit", 20, "offset", 0, "detail", "slim"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("items")) {
    Map<?, ?> item = (Map<?, ?>) row;
    System.out.println(item.get("id") + " " + item.get("name") + " " + item.get("sku"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

